(async () => {
      try {
        setLoading(true);
        setError(null);
        const res = await fetch(`${API_BASE}/api/attendance/share/${slug}`);
        if (!res.ok) throw new Error((await res.text()) || `HTTP ${res.status}`);
        const payload: ShareData = await res.json();
        setData(payload);
      } catch (e: any) {
        setError(e?.message || "공유된 출석을 불러오지 못했어요.");
      } finally {
        setLoading(false);
      }
    })

(async () => {
      try {
        setMyCharacterLoading(true);
        const res = await fetch(`${API_BASE}/api/character/me`, { credentials: "include" });
        if (!res.ok) return;
        const payload: MyCharacterProfile = await res.json();
        setMyCharacter(payload);
      } finally {
        setMyCharacterLoading(false);
      }
    })

(async () => {
      try {
        const res = await fetch(firstImage, { credentials: "include" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const blob = await res.blob();
        objectUrl = URL.createObjectURL(blob);
        if (cancelled) {
          URL.revokeObjectURL(objectUrl);
          objectUrl = null;
          return;
        }
        setCaptureMediaUrl(objectUrl);
        setMediaReady(true);
        setMediaLoadFailed(false);
      } catch {
        const loaded = await waitForImageUrl(firstImage, 9000, 300);
        if (cancelled) return;
        if (loaded) {
          setCaptureMediaUrl(firstImage);
          setMediaReady(true);
          setMediaLoadFailed(false);
        } else {
          setCaptureMediaUrl(null);
          setMediaReady(false);
          setMediaLoadFailed(true);
        }
      }
    })

(async () => {
      try {
        const thumb = await renderAttendanceShareCardPreviewDataUrl({
          date: data.date,
          didWorkout: data.didWorkout,
          workoutTypes: data.workoutTypes ?? [],
          workoutIntensity: data.workoutIntensity ?? null,
          memo: data.memo ?? null,
          shareComment: customMessage || data.shareComment || null,
          mediaUrl: captureMediaUrl,
          nickname: data.authorNickname ?? null,
          theme,
          ratio,
          quoteStyle,
          sticker,
          showMeta,
          mediaFit,
          mediaPositionX,
          mediaPositionY,
          character,
          characterPose,
          characterSize,
          characterLabel: character === "me" ? (data.authorNickname || "내 캐릭터") : "득근이",
          watermarkText: "득근득근",
          cheerCount: data.cheerCount,
          showTitle,
          showSubtitle,
        });
        if (!cancelled) setPreviewThumb(thumb);
      } catch {
        if (!cancelled) setPreviewThumb("");
      }
    })

(async () => {
      try {
        const loungeUrl = API_BASE ? `${API_BASE}/api/lounge/profile` : "/api/lounge/profile";
        const statsUrl = API_BASE ? `${API_BASE}/api/mypage/stats` : "/api/mypage/stats";
        const [loungeRes, statsRes] = await Promise.all([
          fetch(loungeUrl, { credentials: "include" }),
          fetch(statsUrl, { credentials: "include" }),
        ]);

        if (loungeRes.status === 401 || statsRes.status === 401) {
          window.location.href = "/login";
          return;
        }
        if (!loungeRes.ok) {
          const text = await loungeRes.text().catch(() => "");
          throw new Error(text || "Failed to load character data.");
        }
        const loungePayload = (await loungeRes.json()) as LoungeProfileResponse;
        setCharacter(loungePayload.character);
        setRecentAttendanceCount(loungePayload.recentAttendanceCount ?? 0);
        const activeEvent = loungePayload.activeEvents?.[0];
        if (activeEvent) {
          setActiveEventSummary({
            title: activeEvent.title,
            progress: `${activeEvent.currentAttendanceCount}/${activeEvent.requiredAttendanceCount}`,
          });
        } else {
          setActiveEventSummary(null);
        }

        if (statsRes.ok) {
          const statsPayload = await statsRes.json().catch(() => null);
          setMbti(statsPayload?.mbti ?? null);
        }
      } catch (err: any) {
        setError(err?.message ?? "Failed to load character data.");
      } finally {
        setLoading(false);
      }
    })

(async () => {
      try {
        setLoading(true);
        setError(null);
        const monthKey = formatMonthKey(new Date());
        const [pageRes, statsRes, characterRes] = await Promise.all([
          api<MyPageResponse>("/api/mypage"),
          api<UserBodyStats | null>("/api/mypage/stats"),
          api<CharacterProfile>("/api/character/me"),
        ]);
        setData(pageRes);
        setStats(statsRes);
        setCharacter(characterRes);
        setCustomization(loadAvatarCustomization(pageRes.email));
        setSkillEnabledMap(loadSkillToggles(pageRes.email));
        setIsResting(Boolean(characterRes.isResting));
        try {
          const attendanceSummary = await api<AttendanceSummary>(`/api/attendance/summary?month=${monthKey}`);
          setAttendanceCount(attendanceSummary.monthWorkoutCount ?? 0);
        } catch (e) {
          setAttendanceCount(0);
        }
        try {
          const now = new Date();
          const monthKeys = [0, 1, 2].map((offset) =>
            formatMonthKey(new Date(now.getFullYear(), now.getMonth() - offset, 1)),
          );
          const monthLogs = await Promise.all(
            monthKeys.map((key) => api<AttendanceLogLite[]>(`/api/attendance?month=${key}`)),
          );
          const dedup = new Map<string, AttendanceLogLite>();
          monthLogs.flat().forEach((log) => {
            if (!log?.date) return;
            dedup.set(log.date, log);
          });
          setAttendanceLogs(Array.from(dedup.values()));
        } catch {
          setAttendanceLogs([]);
        }
        try {
          const rankRes = await api<RankSummary>("/api/rankings/characters?type=LEVEL&limit=1");
          setRank(rankRes);
        } catch (e) {
          setRank(null);
        }

        if (statsRes) {
          setForm({
            heightCm: statsRes.heightCm?.toString() ?? "",
            gender: statsRes.gender ?? "MALE",
            weightKg: statsRes.weightKg?.toString() ?? "",
            skeletalMuscleKg: statsRes.skeletalMuscleKg?.toString() ?? "",
            bodyFatPercent: statsRes.bodyFatPercent?.toString() ?? "",
            mbti: statsRes.mbti ?? "",
            benchKg: statsRes.benchKg?.toString() ?? "",
            squatKg: statsRes.squatKg?.toString() ?? "",
            deadliftKg: statsRes.deadliftKg?.toString() ?? "",
          });
          try {
            const evalRes = await api<StatsCharacterResponse>("/api/character/evaluate", { method: "POST" });
            setCharacter(evalRes.character);
            setEvaluation(evalRes.evaluation);
            setChange(null);
          } catch (e) {
            setEvaluation(null);
          }
        } else {
          setForm(emptyForm);
        }
      } catch (e: any) {
        setError(e?.message || "마이페이지 정보를 불러오지 못했어요.");
      } finally {
        setLoading(false);
      }
    })
